import { useState, useEffect } from "react";
import axios from "axios";
import CompanyLayout from "./CompanyLayout";

const WILAYAS = ["Alger", "Oran", "Constantine", "Annaba", "Béjaïa", "Tizi Ouzou", "Blida", "Sétif", "Tlemcen", "Batna"];
const TYPES = ["on-site", "remote", "hybrid"];

const ALL_SKILLS = ["React", "Vue", "Angular", "Node.js", "Express", "Django", "FastAPI", "Laravel", "Python", "Java", "PHP", "C++", "SQL", "PostgreSQL", "MongoDB", "Docker", "Git", "Linux", "Flutter", "TypeScript", "Redis", "Kubernetes", "TensorFlow"]
// الحالة الأولية للنموذج (تأكد أن المسميات تطابق الموديل في Django)
const EMPTY_FORM = {
    title: "",
    description: "",
    wilaya: "Alger",
    internship_type: "on-site", // لاحظ استخدام _ لتطابق Django
    domain: "Web Development",
    duration: "6 months",
    skills: [],
    is_active: true,
};



// --- المودال الخاص بالإصافة والتعديل ---
function OfferModal({ offer, onClose, onSave }) {
    const [form, setForm] = useState(offer ? { ...offer } : { ...EMPTY_FORM });
    const upd = (k, v) => setForm(f => ({ ...f, [k]: v }));
    const toggleSkill = s => setForm(f => ({ ...f, skills: f.skills.includes(s) ? f.skills.filter(x => x !== s) : [...f.skills, s] }));
    const isEdit = !!offer?.id;

    const valid = form.title.trim().length > 2 && form.description.trim().length > 10;

    return (
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-box" onClick={e => e.stopPropagation()}>
                <div className="flex items-center justify-between mb-5">
                    <h3 className="font-syne font-extrabold text-slate-900 text-xl">{isEdit ? "Edit offer" : "Post new offer"}</h3>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-xl">✕</button>
                </div>
                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">Job title *</label>
                        <input value={form.title} onChange={e => upd("title", e.target.value)} className="input-field" />
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">Description *</label>
                        <textarea rows={4} value={form.description} onChange={e => upd("description", e.target.value)} className="input-field resize-none" />
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">Wilaya</label>
                            <select value={form.wilaya} onChange={e => upd("wilaya", e.target.value)} className="input-field">
                                {WILAYAS.map(w => <option key={w}>{w}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1.5">Type</label>
                            <select value={form.internship_type} onChange={e => upd("internship_type", e.target.value)} className="input-field">
                                {TYPES.map(t => <option key={t} value={t}>{t.toUpperCase()}</option>)}
                            </select>
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-slate-500 uppercase mb-2">Skills</label>
                        <div className="flex flex-wrap gap-1.5 max-h-32 overflow-y-auto pr-1"></div>
                        {ALL_SKILLS.map(s => (
                                <span key={s} onClick={() => toggleSkill(s)} className={`cursor-pointer text-xs px-2.5 py-1 rounded-full border-2 transition-all ${form.skills.includes(s) ? "bg-blue-600 border-blue-600 text-white" : "bg-white border-slate-200 text-slate-500"}`}>{s}</span>
                            ))}
                        </div>
                    </div>
                    <div className="flex gap-3 pt-1">
                        <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-slate-200 text-sm">Cancel</button>
                        <button onClick={() => valid && onSave(form)} disabled={!valid} className={`flex-1 text-white text-sm font-semibold py-2.5 rounded-xl ${valid ? "shimmer-btn" : "bg-slate-200 cursor-not-allowed"}`}>
                            {isEdit ? "Save changes" : "Post offer"}
                        </button>
                    </div>
                </div>
            </div>
        
    );
}

// --- المودال الخاص بالحذف ---
function DeleteModal({ offer, onClose, onConfirm }) {
    return (
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-box max-w-sm text-center" onClick={e => e.stopPropagation()}>
                <h3 className="font-syne font-bold text-slate-900 text-lg mb-2">Delete this offer?</h3>
                <p className="text-sm text-slate-500 mb-6">"{offer.title}" will be permanently removed.</p>
                <div className="flex gap-3">
                    <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-slate-200">Cancel</button>
                    <button onClick={onConfirm} className="flex-1 danger-btn text-white text-sm font-semibold rounded-xl">Yes, delete</button>
                </div>
            </div>
        </div>
    );
}

// --- الصفحة الرئيسية ---
export default function CompanyOffers() {
    const [offers, setOffers] = useState([]);
    const [modal, setModal] = useState(null);
    const [delModal, setDelModal] = useState(null);
    const [filter, setFilter] = useState("all");
    const [loading, setLoading] = useState(true);

    const API_URL = "http://127.0.0.1:8000/api/offers/";

    // جلب التوكن من localStorage
    const getHeaders = () => {
        const user = JSON.parse(localStorage.getItem("user"));
        return { headers: { Authorization: `Bearer ${user?.access} `} };
    };

    useEffect(() => {
        fetchOffers();
    }, );

    const fetchOffers = async () => {
        try {
            const res = await axios.get(API_URL, getHeaders());
            setOffers(res.data);
        } catch (err) {
            console.error("Fetch error:", err);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async (form) => {
        try {
            if (form.id) {
                const res = await axios.put(`${API_URL}${form.id}/`, form, getHeaders());
                setOffers(prev => prev?.map(o => o.id === form.id ? res.data : o)||[]);
            } else {
                const res = await axios.post(API_URL, form, getHeaders());
                setOffers(prev => [res.data, ...(prev|| [])]);
            }
            setModal(null);
        } catch (err) {
            alert("Error: " + JSON.stringify(err.response?.data));
        }
    };

    const handleDelete = async () => {
        try {
            await axios.delete(`${API_URL}${delModal.id}/`, getHeaders());
            setOffers(prev => prev?.filter(o => o.id !== delModal.id)||[]);
            setDelModal(null);
        } catch (err) {
            alert("Delete failed");
        }
    };

    const filtered = offers.filter(o =>
        filter === "all" ? true : filter === "active" ? o.is_active : !o.is_active
    );
    return (
        <CompanyLayout active="offers">
            <div className="p-5 md:p-8 max-w-4xl mx-auto">
                <div className="flex items-start justify-between mb-6">
                    <div>
                        <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl">Manage offers</h1>
                        <p className="text-slate-400 text-sm mt-0.5">{offers.length} Total Offers</p>
                    </div>
                    <button onClick={() => setModal("create")} className="shimmer-btn text-white text-sm font-semibold px-5 py-2.5 rounded-xl">
                        + Post new offer
                    </button>
                </div>

                <div className="flex gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
                    {[["all", "All"], ["active", "Active"], ["closed", "Closed"]].map(([v, l]) => (
                        <button key={v} onClick={() => setFilter(v)} className={`px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${filter === v ? "bg-white text-blue-600 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}>{l}</button>
                    ))}
                </div>
                <div className="mb-4">
  <label className="block text-sm font-medium text-slate-700 mb-1">Offer Type *</label>
  <select 
    className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-olive-500"
    value={type} 
    onChange={(e) => setType(e.target.value)}
    required
  >
    <option value="">Select Type</option>
    <option value="ON-SITE">On-Site</option>
    <option value="REMOTE">Remote</option>
    <option value="HYBRID">Hybrid</option>
  </select>
</div>

                <div className="space-y-4">
                    {loading ? <p>Loading...</p> : filtered?.map(offer => (
                        <div key={offer.id} className="card border border-slate-200 p-5 bg-white rounded-2xl shadow-sm">
                            <div className="flex items-start justify-between gap-3 mb-3">
                                <div>
                                    <h3 className="font-syne font-bold text-slate-800">{offer.title}</h3>
                                    <p className="text-xs text-slate-400">{offer.wilaya} · {offer.internship_type}</p>
                                </div>
                                <div className="flex gap-2">
                                    <button onClick={() => setModal(offer)} className="text-xs font-semibold px-3 py-1.5 rounded-lg border border-slate-200">Edit</button>
                                    <button onClick={() => setDelModal(offer)} className="text-xs font-semibold px-3 py-1.5 rounded-lg border border-slate-200 text-red-500 hover:bg-red-50">🗑</button>
                                </div>
                            </div>
                            <p className="text-sm text-slate-500 line-clamp-2">{offer.description}</p>
                            <div className="flex flex-wrap gap-1.5 mt-3">
                                {offer.skills?.map(s => <span key={s} className="skill-chip bg-slate-50 px-2 py-1 rounded-md text-xs">{s}</span>)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {modal && <OfferModal offer={modal === "create" ? null : modal} onClose={() => setModal(null)} onSave={handleSave} />}
            {delModal && <DeleteModal offer={delModal} onClose={() => setDelModal(null)} onConfirm={handleDelete} />}
        </CompanyLayout>
    );
}
